const notionBlockId = sessionData.payload?.notionBlockId || sessionData.notionBlockId || '';
const topic = sessionData.payload?.topic || sessionData.topic || 'General';
const callbackId = sessionData.callbackId || '';

if (!tweetText) {
  return [{ json: { error: 'No draft in session payload', callbackId } }];
}

const consumerKey = "9IFkDoCYmP7CJjNptDIcdaImQ";
const consumerSecret = "iYmSxIDay1KiCYTQZ9YzMQ6TEaCKm9LLfQiVOhwfUzJtqgncLy";
const accessToken = "1812047376065916928-OnumkDL0TkxkpKCN1xzrYzs1xGqExO";
const accessTokenSecret = "KZa6INx4ffjVXU0GKZlHwcXRHEunetCqu3B2M4avqTPsY";

// ---- media attach (token from DB via Lookup Session) ----
const TG_BOT_TOKEN = $('PostgreSQL Lookup Session').first().json.tg_token;

function oauthHeaderFor(method, urlStr) {
  const op = {
    oauth_consumer_key: consumerKey,
    oauth_nonce: crypto.randomBytes(16).toString("hex"),
    oauth_signature_method: "HMAC-SHA1",
    oauth_timestamp: Math.floor(Date.now() / 1000).toString(),
    oauth_token: accessToken,
    oauth_version: "1.0",
  };
  const ps = Object.keys(op).sort().map(k => `${encodeURIComponent(k)}=${encodeURIComponent(op[k])}`).join("&");
  const baseStr = `${method}&${encodeURIComponent(urlStr)}&${encodeURIComponent(ps)}`;
  const sk = `${encodeURIComponent(consumerSecret)}&${encodeURIComponent(accessTokenSecret)}`;
  op.oauth_signature = crypto.createHmac("sha1", sk).update(baseStr).digest("base64");
  return "OAuth " + Object.keys(op).sort().map(k => `${encodeURIComponent(k)}="${encodeURIComponent(op[k])}"`).join(", ");
}

function httpsReq(opt, bodyBuf) {
  return new Promise((resolve, reject) => {
    const req = https.request(opt, res => {
      const d = [];
      res.on("data", c => d.push(c));
      res.on("end", () => resolve({ status: res.statusCode, buf: Buffer.concat(d) }));
    });
    req.on("error", reject);
    if (bodyBuf) req.write(bodyBuf);
    req.end();
  });
}

async function tgDownload(fileId) {
  const gf = await httpsReq({ hostname: "api.telegram.org", path: `/bot${TG_BOT_TOKEN}/getFile?file_id=${encodeURIComponent(fileId)}`, method: "GET" });
  const j = JSON.parse(gf.buf.toString("utf8"));
  if (!j.ok) throw new Error("getFile failed: " + gf.buf.toString("utf8").slice(0, 160));
  const fp = j.result.file_path;
  const dl = await httpsReq({ hostname: "api.telegram.org", path: `/file/bot${TG_BOT_TOKEN}/${fp}`, method: "GET" });
  if (dl.status >= 300) throw new Error("tg file download status " + dl.status);
  const lower = fp.toLowerCase();
  const mime = lower.endsWith(".png") ? "image/png" : (lower.endsWith(".webp") ? "image/webp" : "image/jpeg");
  return { bytes: dl.buf, mime };
}

function buildMultipart(fields) {
  const boundary = "----AGSm" + crypto.randomBytes(8).toString("hex");
  const parts = [];
  for (const f of fields) {
    let h = `--${boundary}\r\nContent-Disposition: form-data; name="${f.name}"`;
    if (f.filename) h += `; filename="${f.filename}"`;
    h += "\r\n";
    if (f.contentType) h += `Content-Type: ${f.contentType}\r\n`;
    h += "\r\n";
    parts.push(Buffer.from(h, "utf8"));
    parts.push(f.data ? f.data : Buffer.from(String(f.value), "utf8"));
    parts.push(Buffer.from("\r\n", "utf8"));
  }
  parts.push(Buffer.from(`--${boundary}--\r\n`, "utf8"));
  return { boundary, body: Buffer.concat(parts) };
}

async function uploadMedia(fileId) {
  const { bytes, mime } = await tgDownload(fileId);

  const initUrl = "https://api.x.com/2/media/upload/initialize";
  const initBody = Buffer.from(JSON.stringify({ media_type: mime, total_bytes: bytes.length, media_category: "tweet_image" }), "utf8");
  let r = await httpsReq({ hostname: "api.x.com", path: "/2/media/upload/initialize", method: "POST",
    headers: { "Authorization": oauthHeaderFor("POST", initUrl), "Content-Type": "application/json", "Content-Length": initBody.length } }, initBody);
  const init = JSON.parse(r.buf.toString("utf8"));
  const mediaId = init.data && (init.data.id || init.data.media_id_string);
  if (!mediaId) throw new Error("INIT no media id: " + r.buf.toString("utf8").slice(0, 160));

  const appUrl = `https://api.x.com/2/media/upload/${mediaId}/append`;
  const mp = buildMultipart([{ name: "segment_index", value: "0" }, { name: "media", filename: "m", contentType: mime, data: bytes }]);
  r = await httpsReq({ hostname: "api.x.com", path: `/2/media/upload/${mediaId}/append`, method: "POST",
    headers: { "Authorization": oauthHeaderFor("POST", appUrl), "Content-Type": "multipart/form-data; boundary=" + mp.boundary, "Content-Length": mp.body.length } }, mp.body);
  if (r.status >= 300) throw new Error("APPEND status " + r.status + " " + r.buf.toString("utf8").slice(0, 140));

  const finUrl = `https://api.x.com/2/media/upload/${mediaId}/finalize`;
  r = await httpsReq({ hostname: "api.x.com", path: `/2/media/upload/${mediaId}/finalize`, method: "POST",
    headers: { "Authorization": oauthHeaderFor("POST", finUrl), "Content-Length": 0 } }, null);
  if (r.status >= 300) throw new Error("FINALIZE status " + r.status + " " + r.buf.toString("utf8").slice(0, 140));

  return mediaId; // image needs no processing poll
}
// ---- end media ----

