const action = $json.action;
const prio = action === 'qhigh' ? 1 : (action === 'qlow' ? 3 : 2);
const plabel = action === 'qhigh' ? 'Wysoki' : (action === 'qlow' ? 'Niski' : 'Normalny');
const en = ($json.payload && $json.payload.draft_en) || '';
const esc = (s) => (s || '').replace(/'/g, "''");
return [{ json: { prio, plabel, en_esc: esc(en), chatId: $json.chatId } }];

// Split a Content Creator draft (PL+EN, optionally a numbered series) into individual posts.
const src = $json;
const raw = (src.draft || '').toString();
const ideaId = src.ideaId;
const chatId = src.chatId;
const format = src.format || 'post';
const channel = src.platform || 'x';

// Separate PL and EN sections (markers "=== PL ===" / "=== EN ==="); fallback: whole text = EN
let pl = '', en = '';
const enIdx = raw.search(/===\s*EN\s*===/i);
const plIdx = raw.search(/===\s*PL\s*===/i);
if (enIdx !== -1) {
  en = raw.slice(enIdx).replace(/===\s*EN\s*===/i, '').trim();
  pl = (plIdx !== -1 ? raw.slice(plIdx, enIdx) : raw.slice(0, enIdx)).replace(/===\s*PL\s*===/i, '').trim();
} else {
  en = raw.trim();
  pl = '';
}

// Split a block into numbered posts (1/ , 2) , 3. ...); fallback: one post
function splitSeries(t) {
  if (!t) return [];
  const parts = t.split(/\n(?=\s*\d+\s*[\/\).]\s)/).map(s => s.trim()).filter(Boolean);
  return parts.length ? parts : [t.trim()];
}

let postsEn, postsPl;
if (format === 'series') { postsEn = splitSeries(en); postsPl = splitSeries(pl); }
else { postsEn = [en]; postsPl = [pl]; }

const total = postsEn.length;
const seriesTopic = 'idea:' + ideaId + ':' + format;
const out = [];
for (let i = 0; i < total; i++) {
  const te = (postsEn[i] || '').trim();
  const tp = (postsPl[i] || '').trim();
  const pub = te || tp;
  out.push({ json: {
    pos: i + 1, total: total,
    text_pl: tp, text_en: te,
    pubText: pub, pubTextEsc: pub.replace(/'/g, "''"),
    channel: channel, format: format, ideaId: ideaId, chatId: chatId,
    seriesTopic: seriesTopic
  } });
}
return out;

// callback_data = 'ccp:<rowId>:<action>'  -> Extract Callback Parts (lastIndexOf ':') gives callbackId='ccp:<rowId>', action='<action>'
const c = $json;
const rowId = (c.callbackId || '').split(':')[1] || '';
return [{ json: { rowId: rowId, action: c.action, chatId: c.chatId, callbackQueryId: c.callbackQueryId, messageId: c.messageId } }];

// Publish a single review post to X now. Keys come from CC Fetch For Publish (app_secrets), not hardcoded.
const crypto = require("crypto");
const https = require("https");
const d = $json; // content, ck, cs, at, ats
const rowId = $('Parse CC Post Callback').first().json.rowId;
const chatId = $('Parse CC Post Callback').first().json.chatId;
const tweetText = (d.content || '').toString();
const consumerKey = d.ck, consumerSecret = d.cs, accessToken = d.at, accessTokenSecret = d.ats;
if (!tweetText || !consumerKey) { return [{ json: { ok: false, rowId, chatId, error: 'brak tekstu lub kluczy' } }]; }

function postTweet(text, replyTo) {
  const method = "POST", url = "https://api.twitter.com/2/tweets";
  const op = { oauth_consumer_key: consumerKey, oauth_nonce: crypto.randomBytes(16).toString("hex"), oauth_signature_method: "HMAC-SHA1", oauth_timestamp: Math.floor(Date.now() / 1000).toString(), oauth_token: accessToken, oauth_version: "1.0" };
  const ps = Object.keys(op).sort().map(k => `${encodeURIComponent(k)}=${encodeURIComponent(op[k])}`).join("&");
  const base = `${method}&${encodeURIComponent(url)}&${encodeURIComponent(ps)}`;
  const sk = `${encodeURIComponent(consumerSecret)}&${encodeURIComponent(accessTokenSecret)}`;
  const sig = crypto.createHmac("sha1", sk).update(base).digest("base64");
  const auth = "OAuth " + Object.keys(op).sort().map(k => `${encodeURIComponent(k)}="${encodeURIComponent(op[k])}"`).join(", ") + `, oauth_signature="${encodeURIComponent(sig)}"`;
  const bodyObj = replyTo ? { text, reply: { in_reply_to_tweet_id: replyTo } } : { text };
  const body = JSON.stringify(bodyObj);
  return new Promise((resolve, reject) => {
    const req = https.request({ hostname: "api.twitter.com", path: "/2/tweets", method: "POST", headers: { "Authorization": auth, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, res => { let dd = ""; res.on("data", c => dd += c); res.on("end", () => { try { resolve({ status: res.statusCode, body: JSON.parse(dd) }); } catch (e) { resolve({ status: res.statusCode, body: {} }); } }); });
    req.on("error", reject); req.write(body); req.end();
  });
}

const r = await postTweet(tweetText, null);
const tweetId = (r.body && r.body.data && r.body.data.id) || "";
const tweetUrl = tweetId ? `https://x.com/i/web/status/${tweetId}` : "";
return [{ json: { ok: !!tweetId, tweet_id: tweetId, tweet_url: tweetUrl, rowId: rowId, chatId: chatId, x_status: r.status } }];

// Publish a whole series as a connected X thread (reply-chain). Rows + keys from CC Fetch Series (app_secrets).
const crypto = require("crypto");
const https = require("https");
const rows = $('CC Fetch Series').all().map(i => i.json); // each: id, content, ck, cs, at, ats
const chatId = $('Parse CC Post Callback').first().json.chatId;
if (!rows.length) { return [{ json: { ok: false, chatId, error: 'brak postow serii', rowIdsCsv: '' } }]; }
const k0 = rows[0];
const consumerKey = k0.ck, consumerSecret = k0.cs, accessToken = k0.at, accessTokenSecret = k0.ats;

function postTweet(text, replyTo) {
  const method = "POST", url = "https://api.twitter.com/2/tweets";
  const op = { oauth_consumer_key: consumerKey, oauth_nonce: crypto.randomBytes(16).toString("hex"), oauth_signature_method: "HMAC-SHA1", oauth_timestamp: Math.floor(Date.now() / 1000).toString(), oauth_token: accessToken, oauth_version: "1.0" };
  const ps = Object.keys(op).sort().map(k => `${encodeURIComponent(k)}=${encodeURIComponent(op[k])}`).join("&");
  const base = `${method}&${encodeURIComponent(url)}&${encodeURIComponent(ps)}`;
  const sk = `${encodeURIComponent(consumerSecret)}&${encodeURIComponent(accessTokenSecret)}`;
  const sig = crypto.createHmac("sha1", sk).update(base).digest("base64");
  const auth = "OAuth " + Object.keys(op).sort().map(k => `${encodeURIComponent(k)}="${encodeURIComponent(op[k])}"`).join(", ") + `, oauth_signature="${encodeURIComponent(sig)}"`;
  const bodyObj = replyTo ? { text, reply: { in_reply_to_tweet_id: replyTo } } : { text };
  const body = JSON.stringify(bodyObj);
  return new Promise((resolve, reject) => {
    const req = https.request({ hostname: "api.twitter.com", path: "/2/tweets", method: "POST", headers: { "Authorization": auth, "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, res => { let dd = ""; res.on("data", c => dd += c); res.on("end", () => { try { resolve({ status: res.statusCode, body: JSON.parse(dd) }); } catch (e) { resolve({ status: res.statusCode, body: {} }); } }); });
    req.on("error", reject); req.write(body); req.end();
  });
}

const publishedIds = [], publishedRows = []; let prev = null, firstUrl = '';
for (const row of rows) {
  const r = await postTweet((row.content || '').toString(), prev);
  const tid = (r.body && r.body.data && r.body.data.id) || "";
  if (!tid) {
    return [{ json: { ok: false, chatId, error: 'blad przy poscie ' + (publishedIds.length + 1), count: publishedIds.length, rowIdsCsv: publishedRows.join(','), x_status: r.status, detail: JSON.stringify(r.body).slice(0, 180) } }];
  }
  publishedIds.push(tid); publishedRows.push(row.id); prev = tid;
  if (!firstUrl) firstUrl = `https://x.com/i/web/status/${tid}`;
}
return [{ json: { ok: true, count: publishedIds.length, first_url: firstUrl, rowIdsCsv: publishedRows.join(','), chatId: chatId } }];

const c = $json;
const gateId = (c.callbackId || '').split(':')[1] || '';
const tier = (c.action || '').toLowerCase();
return [{ json: { gateId: gateId, tier: tier, chatId: c.chatId, callbackQueryId: c.callbackQueryId } }];

const c = $json;
const gateId = (c.callbackId || '').split(':')[1] || '';
const decision = (c.action || '').toLowerCase();
return [{ json: { gateId: gateId, decision: decision, chatId: c.chatId, callbackQueryId: c.callbackQueryId } }];

const c = $json;
const itemId = (c.callbackId || '').split(':')[1] || '';
const decision = (c.action || '').toLowerCase();
return [{ json: { itemId: itemId, decision: decision, chatId: c.chatId, callbackQueryId: c.callbackQueryId } }];

parameters.query:
WITH ci AS (
  UPDATE content_items SET status = CASE WHEN '{{ $json.decision }}' = 'approve' THEN 'approved' ELSE 'rejected' END, updated_at=NOW()
   WHERE id = '{{ $json.itemId }}'::uuid AND status='needs_approval' RETURNING id, status, scheduled_for
), pq AS (
  UPDATE post_queue SET status='rejected', updated_at=NOW()
   WHERE content_item_id=(SELECT id FROM ci) AND (SELECT status FROM ci)='rejected' AND status='review' RETURNING id
)
SELECT id AS item_id, status AS item_status FROM ci;

