const raw = $json.rawCallbackData || '';
let v = raw.startsWith('agsel:') ? raw.slice(6) : 'idea';
if (!/^[a-z]+(:[A-Za-z0-9_-]+)*$/.test(v)) v = 'idea';
let label;
let commands;
if (v === 'idea') {
  label = '\u{1F4A1} Idea Bot';
  commands = [{command:'agents',description:'Zmien agenta'},{command:'queue',description:'Kolejka publikacji'},{command:'menu',description:'Menu glowne'}];
} else if (v === 'cm') {
  label = '\u{1F9E0} Content Manager';
  commands = [{command:'agents',description:'Zmien agenta'},{command:'plan',description:'Pokaz plan i kolejke'},{command:'cancel',description:'Anuluj rozmowe'}];
} else {
  const parts = v.split(':');
  label = '\u{1F4E3} Subagent ' + parts.slice(1).join(' ');
  commands = [{command:'agents',description:'Zmien agenta'},{command:'kolejka',description:'Kolejka subagenta'},{command:'raport',description:'Raport subagenta'}];
}
return [{ json: { chat_id: $json.chatId, agent_value: v, label, commandsStr: JSON.stringify(commands) } }];

const p = $('Parse Agsel Callback').first().json;
const tok = $json.tg_token;
const setCmds = { commands: JSON.parse(p.commandsStr), scope: { type: 'chat', chat_id: Number(p.chat_id) } };
const confirm = { chat_id: Number(p.chat_id), text: 'Aktywny agent: ' + p.label + '\nPisz smialo. /agents aby zmienic.' };
return [{ json: { tg_token: tok, setCmdsStr: JSON.stringify(setCmds), confirmStr: JSON.stringify(confirm) } }];

const d = $json;
const chans = typeof d.chans === 'string' ? JSON.parse(d.chans) : (d.chans || []);
const rows = [];
rows.push([{ text: (d.active_agent === 'idea' ? '\u2705 ' : '') + '\u{1F4A1} Idea Bot (pomysly)', callback_data: 'agsel:idea' }]);
rows.push([{ text: (d.active_agent === 'cm' ? '\u2705 ' : '') + '\u{1F9E0} Content Manager', callback_data: 'agsel:cm' }]);
for (const c of chans) {
  const v = 'subagent:' + c.brand_id + ':' + c.channel;
  rows.push([{ text: (d.active_agent === v ? '\u2705 ' : '') + '\u{1F4E3} ' + c.brand_id + ' ' + c.channel, callback_data: 'agsel:' + v }]);
}
rows.push([{ text: '\u2699\uFE0F Cele (wlacz/wylacz)', callback_data: 'cele:list' }]);
const body = { chat_id: Number($('Detect Update Type').first().json.chat_id), text: 'Wybierz aktywnego agenta:', reply_markup: { inline_keyboard: rows } };
return [{ json: { tg_token: d.tg_token, tgBodyStr: JSON.stringify(body) } }];

