const raw = $json.rawCallbackData || '';
const parts = raw.split(':');
let taskType = parts[1] || '';
let tier = parts[2] || '';
if (!/^[a-z_]{2,30}$/.test(taskType)) taskType = 'canonical';
if (!['haiku','sonnet','opus'].includes(tier)) tier = 'sonnet';
return [{ json: { chat_id: $json.chatId, task_type: taskType, tier } }];

const p = $('Parse Cmtier Callback').first().json;
const body = { chat_id: Number(p.chat_id),
  text: '🎚 Model dla zadania "' + p.task_type + '": ' + p.tier + '. Zapamietane (gate zapisany), dziala od nastepnego zadania.' };
return [{ json: { tg_token: $json.tg_token, tgBodyStr: JSON.stringify(body) } }];

let chat = null;
try { chat = $('Extract Callback Parts').first().json.chatId; } catch (e) {}
if (!chat) { try { chat = $('Detect Update Type').first().json.chat_id; } catch (e) {} }
const t = typeof $json.t === 'string' ? JSON.parse($json.t) : ($json.t || []);
const ICON = { active: '\u2705', draft: '\u2705', paused: '\u23F8', ready: '\u{1F550}' };
const rows = [];
const lines = ['\u2699\uFE0F Cele publikacji (tap = wlacz/wstrzymaj):'];
for (const x of t) {
  const ic = ICON[x.s] || '?';
  lines.push(ic + ' ' + x.b + ' ' + x.c + ' | ' + (x.lang || '?') + ' | ' + x.wm + ' | ' + x.s);
  rows.push([{ text: ic + ' ' + x.b + ' ' + x.c, callback_data: 'tgl:' + x.b + ':' + x.c }]);
}
lines.push('', 'Nowy cel / zmiana konfiguracji: napisz do Content Managera (np. "dodaj cel instagram dla AGS jak linkedin").');
const body = { chat_id: Number(chat), text: lines.join('\n'), reply_markup: { inline_keyboard: rows } };
return [{ json: { tg_token: $json.tg_token, tgBodyStr: JSON.stringify(body) } }];

const raw = $json.rawCallbackData || '';
const parts = raw.split(':');
let b = parts[1] || '', c = parts[2] || '';
if (!/^[A-Za-z0-9_-]{1,50}$/.test(b)) b = '';
if (!/^[a-z0-9_]{1,40}$/.test(c)) c = '';
return [{ json: { b, c, chat_id: $json.chatId } }];

const p = $('Parse Tgl Callback').first().json;
const r = $json;
let text;
if (!r.channel) { text = 'Nie znam celu ' + p.b + '/' + p.c + '.'; }
else if (r.status === 'active' && r.old_status !== 'active') { text = '\u2705 Wlaczony: ' + p.b + ' ' + p.c + '. CM zaraz przywita go propozycjami z archiwum.'; }
else if (r.status === 'paused') { text = '\u23F8 Wstrzymany: ' + p.b + ' ' + p.c + ' (nic nie publikuje, konfiguracja zostaje).'; }
else {
  const braki = [];
  if (!r.has_token) braki.push('token w sejfie (prefix)');
  if (!r.has_org) braki.push('org_urn strony');
  text = '\u26A0\uFE0F Nie moge wlaczyc ' + p.b + ' ' + p.c + ' - brakuje: ' + braki.join(', ') + '. Uzupelnij i sprobuj ponownie.';
}
const body = { chat_id: Number(p.chat_id), text };
return [{ json: { tg_token: r.tg_token, tgBodyStr: JSON.stringify(body) } }];

const d = $json;
const secs = d.duration ? (' ' + d.duration + 's') : '';
let content = (d.caption ? d.caption + ' | ' : '') + '(wideo' + secs + ')';
if ((d.size || 0) > 19 * 1024 * 1024) { content += ' [UWAGA: plik >19MB - publikacja przez Telegram niemozliwa, potrzebny GDrive]'; }
const meta = { chat_id: d.chat_id, idea_type: 'video', media: { file_id: d.file_id, kind: 'video', duration: d.duration || 0, size: d.size || 0 } };
return [{ json: { contentEsc: content.replace(/'/g, "''"), metadataEsc: JSON.stringify(meta).replace(/'/g, "''"), chat_id: d.chat_id } }];

const save = $('Save Idea').first().json;
const act = ($json.active_agent || '').toString();
let maddFresh = false;
try { const st = JSON.parse(save.madd || '{}'); maddFresh = !!(st.item_id && st.ts && (Date.now() - new Date(st.ts).getTime()) < 10 * 60 * 1000); } catch (e) {}
// #88: zdjecie idzie do ROZMOWY aktywnego agenta (subagent LUB cm); triage TYLKO dla Idea Bota
let go = 'triage', text = '';
if (!maddFresh && save.idea_type === 'photo') {
  if (act.indexOf('subagent:') === 0) { go = 'conversation'; text = 'skomentuj ostatni zrzut'; }
  else if (act === 'cm') { go = 'conversation'; text = 'przeslalem ci zrzut ekranu (masz go w schowku)'; }
}
return [{ json: { go, text, id: save.id, content: save.content, chat_id: save.chat_id, madd: save.madd, secret: $json.secret || '' } }];
